.vs, .vs-stage { container-type: inline-size; }
.vs-stage { box-sizing: border-box; aspect-ratio: 16 / 9; width: min(100%, calc(var(--room, 70dvh) * 16 / 9)); margin-inline: auto; overflow: clip;
  background: var(--color-panel); border: 1px solid var(--color-border-line); border-radius: var(--cds-radius); }
@container (max-width: 800px) { .vs-stage { aspect-ratio: 1; width: min(100%, var(--room, 70dvh)); } }
@container (max-width: 560px) { .vs-stage { aspect-ratio: 4 / 5; width: min(100%, calc(var(--room, 70dvh) * 4 / 5)); } }
.vs-in { box-sizing: border-box; height: 100%; padding: 0 3.6cqi 3cqi; display: grid; grid-template-rows: auto minmax(0, 1fr); position: relative; }
.vs-chapters { display: grid; box-sizing: border-box; isolation: isolate; }
.vs-in, .vs-chapters, .vs-ch { grid-template-columns: minmax(0, 1fr); }
.vs-ch, .vs-cap { margin: 0; opacity: 0; transition: opacity 400ms var(--cds-ease-out); }
.vs-ch.vs-on, .vs-cap.vs-on { opacity: 1; } .vs-ch:not(.vs-on) { pointer-events: none; }
.vs-ch { grid-area: 1 / 1; display: grid; grid-template-rows: auto auto auto minmax(0, 1fr) auto; }
.vs-say { grid-row: 3; } .vs-draw { grid-row: 4; } .vs-src { grid-row: 5; }
.vs-draw { container-type: size; display: flex; flex-direction: column; justify-content: safe center; font-size: max(12px, 1.8cqi); }
.vs-in { --marks: max(24px, 4cqi); --row: 32px; --ctl: 176px; }
@media (pointer: coarse) { .vs-in { --marks: max(32px, 4cqi); --row: 52px; --ctl: 240px; } }
.vs-line { grid-area: 1 / 1; height: var(--marks); display: flex; gap: 6px; }
.vs-mk { flex: 1; min-inline-size: 0; position: relative; display: flex; align-items: center; padding: 0; border: 0; background: none; cursor: pointer; forced-color-adjust: none; outline-offset: -3px; }
.vs-mk::before { content: ''; position: absolute; inset-inline: 0; background: var(--cds-chart-muted); }
.vs-mk i { position: relative; display: block; width: 0; background: var(--color-fg); }
.vs-mk::before, .vs-mk i { height: 3px; border-radius: 3px; }
@media (forced-colors: active) { .vs-mk::before { background: GrayText; } .vs-mk i { background: CanvasText; } }
.vs-chapters, .vs-caps { grid-area: 2 / 1; }
.vs-caps, .vs-say { font-size: max(14px, 2cqi); line-height: 1.4; }
.vs-say { block-size: 2lh; } .vs-ch h2 { margin: 0.1em 0 0.3em; }
.vs-cap { position: absolute; inset-inline: 3.6cqi; display: grid; font-weight: var(--cds-font-weight-medium); }
.vs-s { grid-area: 1 / 1; opacity: 0; } .vs-s.vs-on { opacity: 1; }
.vs-caps { pointer-events: none; } .vs-hush .vs-caps { opacity: 0; }
.vs-label { margin: 0; padding-block: calc((var(--row) - 1lh) / 2); padding-inline-end: var(--ctl); text-transform: uppercase; }
.vs-controls { position: absolute; inset-block-start: var(--marks); inset-inline-end: calc(3.6cqi - 6px); height: var(--row); display: flex; align-items: center; gap: 8px; }
.vs-controls { transition: opacity 200ms var(--cds-ease-out); }
@media (hover: hover) { .vs-playing .vs-stage:is(.vs-idle:not(.vs-held), :not(:hover, .vs-touch)):not(:has(:focus-visible)) .vs-controls { opacity: 0; transition: opacity var(--cds-dur-slow) var(--cds-ease-out) 300ms; } }
@media (prefers-reduced-motion: reduce) { .vs-controls { transition: none !important; } }
.vs-controls > button { flex: none; height: calc(100% - 8px); min-inline-size: 24px; padding-inline: 6px; font: inherit; font-size: 13px; color: var(--color-fg); background: none; border: 0; border-radius: 6px; cursor: pointer; }
@media (hover: hover) { .vs-controls > button:hover { background: var(--cds-border); } .vs-mk:hover::before, .vs-mk:hover i { height: 5px; } }
.vs-controls > button:has(svg) { display: grid; place-items: center; padding-inline: 4px; }
.vs-controls svg { grid-area: 1 / 1; inline-size: 16px; block-size: 16px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; }
@media (pointer: coarse) { .vs-controls > button:has(svg) { min-inline-size: 40px; } .vs-controls svg { inline-size: 20px; block-size: 20px; } }
.vs-cc[aria-pressed="false"] { color: var(--color-fg-muted); text-decoration: line-through; }
.vs.vs-playing .vs-toggle > :first-child, .vs:not(.vs-playing) .vs-toggle > :last-child { visibility: hidden; }
[data-read-sound][aria-pressed="true"] > :first-child, [data-read-sound]:not([aria-pressed="true"]) > :last-child { visibility: hidden; }
@container (max-width: 560px) { .vs-line { gap: 4px; } .vs-say { block-size: 3lh; } .vs-chapters { padding-top: calc(var(--row) + 4px); } .vs-label { padding: 0; } }
.vs-now { position: absolute; width: 1px; height: 1px; margin: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media print {
  .vs-stage { aspect-ratio: auto; width: 100%; border: 0; background: none; } .vs-line, .vs-controls { display: none; }
  .vs-ch { grid-area: auto; opacity: 1; aspect-ratio: 16 / 10; } .vs-ch + .vs-ch { break-before: page; }
  .vs-say { block-size: 4lh; } .vs-cap { display: block; } .vs-cap, .vs-s, .vs-hush .vs-caps { opacity: 1; }
}

/* ---- This piece: chapter frame ---- */
.vs-label { font-size: max(11px, 1.2cqi); letter-spacing: 0.08em; color: var(--color-fg-muted); }
.vs-ch h2 { font-family: var(--font-anthropic-serif); font-weight: 400; font-size: max(18px, 3.4cqi); line-height: 1.15; text-wrap: balance; color: var(--color-fg); }
.vs-src { margin: 0.6em 0 0; font-size: max(11px, 1.3cqi); color: var(--color-fg-muted); }
.vs-big { margin: 0; text-align: center; font-family: var(--font-anthropic-serif); font-weight: 400; font-size: 12cqi; line-height: 1; color: var(--color-fg); font-variant-numeric: tabular-nums; }
.vs-bigsub { margin: 0.4em auto 0; max-width: 46ch; text-align: center; font-size: max(13px, 1.8cqi); color: var(--color-fg-muted); text-wrap: balance; }

/* ---- Bar charts: rows of label | track | value, sharing the drawing's height ---- */
.vz { position: relative; height: 100%; display: flex; flex-direction: column; }
.vz-key { display: flex; gap: 1.2em; justify-content: flex-end; font-size: 0.9em; color: var(--color-fg-muted); padding-bottom: 0.3em; }
.vz-key i { display: inline-block; width: 0.8em; height: 0.8em; border-radius: 2px; margin-right: 0.35em; vertical-align: -0.05em; forced-color-adjust: none; }
.vz-rows { flex: 1; min-height: 0; display: grid; grid-auto-rows: minmax(0, 1fr); align-content: center; }
.vz-row { display: grid; grid-template-columns: minmax(0, 32%) minmax(0, 1fr) 5.2em; align-items: center; gap: 0.7em; min-height: 0; }
.vz-lab { text-align: right; color: var(--color-fg); line-height: 1.15; overflow-wrap: anywhere; }
.vz-track { position: relative; height: 62%; max-height: 2.4em; min-height: 0.6em; }
.vz-pair .vz-track { height: 80%; max-height: 3em; }
.vz-b { position: absolute; top: 0; bottom: 0; border-radius: 3px; background: var(--cds-chart-muted); forced-color-adjust: none; transform-origin: left center; }
.vz-pair .vz-b.vz-us { top: 0; bottom: 52%; } .vz-pair .vz-b.vz-cn { top: 52%; bottom: 0; }
.vz-v { font-variant-numeric: tabular-nums; color: var(--color-fg); white-space: nowrap; line-height: 1.15; }
.vz-v small { color: var(--color-fg-muted); font-size: 0.85em; }
.vz-mid { position: absolute; top: -12%; bottom: -12%; width: 1px; background: var(--cds-chart-reference); }
.vz-ref { position: absolute; top: -18%; bottom: -18%; width: 2px; background: var(--color-fg); border-radius: 1px; }
.vz-refnote { position: absolute; bottom: 100%; transform: translateX(-50%); font-size: 0.8em; color: var(--color-fg-muted); white-space: nowrap; }
.vz-tip { position: absolute; z-index: 2; pointer-events: none; max-width: 22em; padding: 0.4em 0.6em; font-size: 0.85em; line-height: 1.3;
  background: var(--cds-surface-popover); border: 1px solid var(--cds-border); box-shadow: var(--cds-shadow-popover); border-radius: 6px; color: var(--color-fg); }
.vz-tip small { display: block; color: var(--cds-text-secondary); }
.vz-list { margin: 0 auto; padding: 0; list-style: none; display: grid; gap: 0.9em; max-width: 60ch; font-size: max(13px, 1.9cqi); line-height: 1.35; }
.vz-list li { padding-left: 1em; border-left: 3px solid var(--cds-chart-muted); color: var(--color-fg); }
.vz-list b { font-weight: var(--cds-font-weight-medium); }
@container (max-width: 560px) { .vz-row { grid-template-columns: minmax(0, 38%) minmax(0, 1fr) 4.4em; gap: 0.4em; } }
